Nat4	loadPersistents_Project_20_Build_20_Activity(V_Environment environment);
Nat4	loadPersistents_Project_20_Build_20_Activity(V_Environment environment)
{
	V_Value tempPersistent = NULL;
	V_Dictionary dictionary = environment->persistentsTable;

	tempPersistent = create_persistentNode("Default Bundle Identifier Prefix",tempPersistent_Default_20_Bundle_20_Identifier_20_Prefix,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("Last Form",NULL,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("Default Forms List",tempPersistent_Default_20_Forms_20_List,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("Bundle Packager Form/Link States",tempPersistent_Bundle_20_Packager_20_Form_2F_Link_20_States,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("MacOS Bundle Form/Link States",tempPersistent_MacOS_20_Bundle_20_Form_2F_Link_20_States,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("Standard Platform Binary/Link States",tempPersistent_Standard_20_Platform_20_Binary_2F_Link_20_States,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("MacOS Platform Application/Link States",tempPersistent_MacOS_20_Platform_20_Application_2F_Link_20_States,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	return kNOERROR;

}

Nat4	load_Project_20_Build_20_Activity(V_Environment environment);
Nat4	load_Project_20_Build_20_Activity(V_Environment environment)
{

	loadClasses_Project_20_Build_20_Activity(environment);
	loadUniversals_Project_20_Build_20_Activity(environment);
	loadPersistents_Project_20_Build_20_Activity(environment);
	return kNOERROR;

}

